export function defaultBuild(){return {fans:[...Array.from({length:3},(_,i)=>({id:'front'+i,name:`Front-right ${i+1}`,type:'stock',rpm:1200,intake:true,on:true})),...Array.from({length:2},(_,i)=>({id:'bottom'+i,name:`Bottom ${i+1}`,type:'p14',rpm:1100,intake:true,on:true})),{id:'rear',name:'Rear',type:'p12',rpm:1100,intake:false,on:true},...Array.from({length:2},(_,i)=>({id:'top'+i,name:`Radiator ${i+1}`,type:'ml120',rpm:1100,intake:false,on:true}))],gpuWatts:450,cpuWatts:75,otherWatts:60,radiator:'exhaust'};}
export function buildTotals(s){let intake=0,exhaust=0;for(const f of s.fans){const spec=BUILD.fanTypes[f.type];if(!f.on)continue;const q=spec.cfm*Math.max(0,Math.min(f.rpm,spec.maxRPM))/spec.maxRPM;f.intake?intake+=q:exhaust+=q;}return {intake,exhaust,heat:s.gpuWatts+s.cpuWatts+s.otherWatts,lengthMargin:BUILD.case.gpuClearance-BUILD.gpu.length,radStack:BUILD.aio.thickness+BUILD.aio.fanThickness};}
